input.command:
python3 - <<'PY'
import json,glob
for f in sorted(glob.glob('transcripts/harness_*/main.jsonl')):
    sub=cr=sl=0; auto=0
    for line in open(f):
        try: d=json.loads(line)
        except: continue
        m=d.get('message') or {}
        c=m.get('content')
        if isinstance(c,list):
            for b in c:
                if isinstance(b,dict) and b.get('type')=='tool_use':
                    n=b.get('name','')
                    if n.endswith('subscribe_pr_activity') and 'unsub' not in n: sub+=1
                    if n.endswith('create_pull_request'): cr+=1
                    if n.endswith('send_later'): sl+=1
                if isinstance(b,dict) and b.get('type')=='tool_result' and 'subscribed' in json.dumps(b.get('content'))[:3000].lower() and 'create' in json.dumps(b.get('content'))[:300].lower(): auto+=1
    print(f.split('/')[1], 'subscribe',sub,'create_pr',cr,'send_later',sl,'create_result_mentions_subscribed',auto)
PY

